import {COTS_STATUSES,cotsStatus,toOrder,validCots,safeProductUrl,vendorName,selectWcpVariant,wcpCartLink,orderList} from './cots-model.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function cotsTable(items){return `<div class="table-wrap"><table><thead><tr><th>Part</th><th>Vendor</th><th>Need</th><th>Ordered</th><th>Received</th><th>Status</th><th>Expected</th><th></th></tr></thead><tbody>${items.map(i=>{const status=cotsStatus(i);return `<tr><td><button class="part-name" data-edit="${esc(i.id)}">${esc(i.name)}</button><div class="part-number">${esc(i.number||'No part number')}${safeProductUrl(i.url)?` · <a class="drawing-link" href="${esc(safeProductUrl(i.url))}" target="_blank" rel="noopener noreferrer">Product ↗</a>`:''}</div></td><td>${esc(vendorName(i.vendor))}</td><td>${i.needed}</td><td>${i.ordered}</td><td>${i.received}</td><td><span class="status ${status==='Received'?'complete':status==='Need to order'?'blocked':''}">${status}</span></td><td>${i.eta?esc(new Date(i.eta+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'})):'-'}</td><td>${toOrder(i)>0?`<button class="secondary cots-quick" data-cots-order="${esc(i.id)}">Mark ordered</button>`:i.received<i.ordered?`<button class="secondary cots-quick" data-cots-receive="${esc(i.id)}">Mark received</button>`:''}</td></tr>`;}).join('')}</tbody></table></div>`;}
export function vendorOrders(items){const groups=new Map();for(const item of items.filter(i=>toOrder(i)>0)){const vendor=vendorName(item.vendor);if(!groups.has(vendor))groups.set(vendor,[]);groups.get(vendor).push(item);}return [...groups].map(([vendor,rows])=>`<div class="vendor-order"><div><strong>${esc(vendor)}</strong><span>${rows.length} items · ${rows.reduce((n,i)=>n+toOrder(i),0)} to order</span></div><button class="secondary" data-vendor-cart="${esc(vendor)}">${vendor==='WCP'?'Add to cart':'Order list'}</button></div>`).join('');}
export function initCots({getWorkspace,save,onChanged,toast}){
 const $=s=>document.querySelector(s);let editing=null,cartItems=[],preparing=false;
 const field=(name,label,type='text',value='',extra='')=>`<label ${name==='name'||name==='url'?'class="full"':''}>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra} maxlength="500"></label>`;
 function edit(id){editing=id||null;const i=getWorkspace().cots.find(i=>i.id===id)||{};$('#cots-title').textContent=id?'Edit COTS part':'Add COTS part';$('#cots-delete').hidden=!id;$('#cots-fields').innerHTML=field('name','Part name','text',i.name,'required')+field('vendor','Vendor','text',vendorName(i.vendor||''),'required list="vendor-options"')+field('number','Vendor part number','text',i.number)+field('url','Product link','url',i.url)+field('needed','Quantity needed','number',i.needed??1,'required min="1" step="1"')+field('ordered','Quantity ordered','number',i.ordered??0,'required min="0" step="1"')+field('received','Quantity received','number',i.received??0,'required min="0" step="1"')+field('eta','Expected delivery','date',i.eta)+field('reference','Order / PO number','text',i.reference)+`<label class="full">Notes<textarea name="notes" rows="3" maxlength="10000">${esc(i.notes||'')}</textarea></label>`;$('#cots-dialog').showModal();}
 $('#cots-form').onsubmit=e=>{e.preventDefault();const item=Object.fromEntries(new FormData(e.target));Object.keys(item).forEach(k=>item[k]=item[k].trim());item.id=editing||crypto.randomUUID();item.vendor=vendorName(item.vendor);for(const k of ['needed','ordered','received'])item[k]=Number(item[k]);if(!validCots([item])){toast('Check quantities. Received cannot exceed ordered.');return;}const state=getWorkspace();const prior=state.cots.find(i=>i.id===editing);if(prior?.onshape)item.onshape={...prior.onshape};const next={...state,cots:editing?state.cots.map(i=>i.id===editing?item:i):[...state.cots,item]};if(save(next)){$('#cots-dialog').close();onChanged();toast('COTS part saved');}};
 $('#cots-delete').onclick=()=>{if(!confirm('Delete this COTS part?'))return;const s=getWorkspace();if(save({...s,cots:s.cots.filter(i=>i.id!==editing)})){$('#cots-dialog').close();onChanged();toast('COTS part deleted');}};
 ['#close-cots','#cancel-cots'].forEach(s=>$(s).onclick=()=>$('#cots-dialog').close());
 function quick(id,receive){const state=getWorkspace();if(save({...state,cots:state.cots.map(i=>i.id===id?(receive?{...i,received:i.ordered}:{...i,ordered:Math.max(i.needed,i.ordered)}):i)})){onChanged();toast(receive?'Received quantity updated':'Marked as ordered');}}
 async function cart(vendor){if(preparing)return;cartItems=getWorkspace().cots.filter(i=>vendorName(i.vendor)===vendor&&toOrder(i)>0);$('#cart-title').textContent=vendor==='WCP'?'WCP cart':vendor+' order list';$('#cart-dialog').showModal();$('#cart-link').hidden=true;$('#cart-body').innerHTML='<p>Preparing order list…</p>';if(!cartItems.length){$('#cart-body').textContent='No items need ordering.';return;}const list=`<div class="onshape-list">${cartItems.map(i=>`<div><strong>${esc(i.number||i.name)}</strong><span>${toOrder(i)} × ${esc(i.name)}</span></div>`).join('')}</div>`;
  if(vendor!=='WCP'){$('#cart-body').innerHTML='<p>Bulk cart links are not available for this vendor. Copy the list and add items on the vendor’s site.</p>'+list+`<div class="vendor-products">${cartItems.filter(i=>safeProductUrl(i.url)).map(i=>`<a class="drawing-link" href="${esc(safeProductUrl(i.url))}" target="_blank" rel="noopener noreferrer">${esc(i.number||i.name)} ↗</a>`).join('')}</div>`;return;}
  preparing=true;try{const lines=[],errors=[];const cache=new Map();for(const item of cartItems){try{const key=item.url.split('?')[0];if(!cache.has(key)){const response=await fetch('/api/vendors/wcp/product?url='+encodeURIComponent(item.url));const data=await response.json();if(!response.ok)throw Error(data.error||'Could not load the WCP product.');cache.set(key,data.variants);}const variant=selectWcpVariant(cache.get(key),item);if(!variant.available)throw Error('This product option is unavailable.');lines.push({variant:variant.id,quantity:toOrder(item)});}catch(err){errors.push(`${item.number||item.name}: ${err.message}`);}}
   if(errors.length){$('#cart-body').innerHTML='<p class="cart-error">Cart not created. Fix these items so the whole order can be included.</p><ul>'+errors.map(e=>`<li>${esc(e)}</li>`).join('')+'</ul>'+list;return;}
   $('#cart-link').href=wcpCartLink(lines);$('#cart-link').hidden=false;$('#cart-body').innerHTML='<p>Opens WCP’s cart with the quantities still to order. This may replace your existing WCP cart. Review it before checkout. Items remain unmarked until you record the order.</p>'+list;
  }catch(err){$('#cart-body').textContent=err.message;}finally{preparing=false;}}
 $('#close-cart').onclick=()=>$('#cart-dialog').close();$('#copy-order').onclick=async()=>{try{await navigator.clipboard.writeText(orderList(cartItems));toast('Order list copied');}catch{$('#cart-copy-text').hidden=false;$('#cart-copy-text').value=orderList(cartItems);$('#cart-copy-text').select();toast('Select and copy the order list');}};
 return {edit,quick,cart};
}
